CREATE TABLE Alert_Log (AlertID NUMBER GENERATED BY DEFAULT AS IDENTITY, ParentID NUMBER, Message CLOB, Timestamp TIMESTAMP, Title VARCHAR2(255 CHAR) NOT NULL, Content CLOB, CONSTRAINT Alert_Log_PK PRIMARY KEY (AlertID));
CREATE TABLE Attendance (AttendanceID NUMBER GENERATED BY DEFAULT AS IDENTITY, EnrollmentID NUMBER, SessionDate DATE, Status VARCHAR2(20 CHAR), CONSTRAINT Attendance_PK PRIMARY KEY (AttendanceID));
CREATE TABLE Course_Sessions (CourseSessionID NUMBER GENERATED BY DEFAULT AS IDENTITY, CourseID NUMBER, SessionID NUMBER, CONSTRAINT Course_Sessions_PK PRIMARY KEY (CourseSessionID));
CREATE TABLE Courses (CourseID NUMBER GENERATED BY DEFAULT AS IDENTITY, CourseName VARCHAR2(100 CHAR), CourseDescription CLOB, CourseFee NUMBER(10,2), CourseCode VARCHAR2(50 CHAR), CreditHours NUMBER, SemesterID NUMBER, CONSTRAINT Courses_PK PRIMARY KEY (CourseID));
CREATE TABLE Enrollments (EnrollmentID NUMBER GENERATED BY DEFAULT AS IDENTITY, StudentID VARCHAR2(255 CHAR), CourseID NUMBER, EnrollmentDate DATE, Status VARCHAR2(50 CHAR) DEFAULT 'Enrolled', SessionID NUMBER, CONSTRAINT Enrollments_PK PRIMARY KEY (EnrollmentID));
CREATE TABLE Events (EventID NUMBER GENERATED BY DEFAULT AS IDENTITY, CourseID NUMBER, EventName VARCHAR2(100 CHAR), EventType VARCHAR2(50 CHAR), EventDate DATE, CONSTRAINT Events_PK PRIMARY KEY (EventID));
CREATE TABLE Grades (GradeID NUMBER GENERATED BY DEFAULT AS IDENTITY, EnrollmentID NUMBER, GradePercentage NUMBER(5,2), GradeLetter VARCHAR2(5 CHAR), GradedByUserID NUMBER, GradeDate DATE, CONSTRAINT Grades_PK PRIMARY KEY (GradeID));
CREATE TABLE Messages (MessageID NUMBER GENERATED BY DEFAULT AS IDENTITY, SenderUserID NUMBER, ReceiverUserID NUMBER, Subject VARCHAR2(255 CHAR), Content CLOB, Timestamp TIMESTAMP DEFAULT SYSTIMESTAMP, IsRead NUMBER(1) DEFAULT 0, DeletedBySender NUMBER(1) DEFAULT 0, DeletedByReceiver NUMBER(1) DEFAULT 0, CONSTRAINT Messages_PK PRIMARY KEY (MessageID));
CREATE TABLE Notifications (NotificationID NUMBER GENERATED BY DEFAULT AS IDENTITY, UserID NUMBER, UserRole VARCHAR2(50 CHAR), Message CLOB, Timestamp TIMESTAMP DEFAULT SYSTIMESTAMP, IsRead NUMBER(1) DEFAULT 0, Link VARCHAR2(255 CHAR), Type VARCHAR2(50 CHAR), CONSTRAINT Notifications_PK PRIMARY KEY (NotificationID));
CREATE TABLE Parents (ParentID NUMBER GENERATED BY DEFAULT AS IDENTITY, FirstName VARCHAR2(50 CHAR), LastName VARCHAR2(50 CHAR), Phone VARCHAR2(20 CHAR), UserID NUMBER, CONSTRAINT Parents_PK PRIMARY KEY (ParentID), CONSTRAINT UQ_Parents_UserID UNIQUE (UserID));
CREATE TABLE Payments (PaymentID NUMBER GENERATED BY DEFAULT AS IDENTITY, EnrollmentID NUMBER, Amount NUMBER(10,2), PaymentDate DATE, CONSTRAINT Payments_PK PRIMARY KEY (PaymentID));
CREATE TABLE Schedules (ScheduleID NUMBER GENERATED BY DEFAULT AS IDENTITY, CourseID NUMBER, DayOfWeek VARCHAR2(10 CHAR), StartTime VARCHAR2(10), EndTime VARCHAR2(10), Room VARCHAR2(50 CHAR), TeacherUserID NUMBER, CONSTRAINT Schedules_PK PRIMARY KEY (ScheduleID));
CREATE TABLE Semesters (SemesterID NUMBER GENERATED BY DEFAULT AS IDENTITY, SemesterName VARCHAR2(50 CHAR) NOT NULL, SemesterLevel NUMBER NOT NULL, CONSTRAINT Semesters_PK PRIMARY KEY (SemesterID));
CREATE TABLE Sessions (SessionID NUMBER GENERATED BY DEFAULT AS IDENTITY, SessionName VARCHAR2(50 CHAR) NOT NULL, Year NUMBER NOT NULL, Term VARCHAR2(20 CHAR) NOT NULL, CONSTRAINT Sessions_PK PRIMARY KEY (SessionID));
CREATE TABLE Students (StudentID VARCHAR2(255 CHAR) NOT NULL, UserID NUMBER, StudentName VARCHAR2(255 CHAR) NOT NULL, Phone VARCHAR2(20 CHAR), DOB DATE, RegistrationCode VARCHAR2(255 CHAR), Status VARCHAR2(50 CHAR) DEFAULT 'Pending', ParentNameProvided VARCHAR2(255 CHAR), ParentEmailProvided VARCHAR2(255 CHAR), ParentPhoneProvided VARCHAR2(255 CHAR), CONSTRAINT Students_PK PRIMARY KEY (StudentID), CONSTRAINT UQ_Students_UserID UNIQUE (UserID), CONSTRAINT UQ_Students_RegCode UNIQUE (RegistrationCode));
CREATE TABLE Teachers (TeacherID VARCHAR2(255 CHAR) NOT NULL, UserID NUMBER, TeacherName VARCHAR2(255 CHAR) NOT NULL, SubjectTaught VARCHAR2(255 CHAR), Email VARCHAR2(255 CHAR), Phone VARCHAR2(20 CHAR), DOB DATE, RegistrationCode VARCHAR2(255 CHAR), Status VARCHAR2(50 CHAR) DEFAULT 'Pending', CONSTRAINT Teachers_PK PRIMARY KEY (TeacherID), CONSTRAINT UQ_Teachers_UserID UNIQUE (UserID), CONSTRAINT UQ_Teachers_RegCode UNIQUE (RegistrationCode));
CREATE TABLE Users (UserID NUMBER GENERATED BY DEFAULT AS IDENTITY, Username VARCHAR2(50 CHAR), PasswordHash VARCHAR2(255 CHAR), UserType VARCHAR2(20 CHAR), ParentID NUMBER, RegistrationCode VARCHAR2(255 CHAR), AdminName VARCHAR2(255 CHAR), Email VARCHAR2(255 CHAR), IsActive NUMBER(1) DEFAULT 1, CONSTRAINT Users_PK PRIMARY KEY (UserID), CONSTRAINT UQ_Users_Username UNIQUE (Username), CONSTRAINT UQ_Users_RegCode UNIQUE (RegistrationCode), CONSTRAINT UQ_Users_Email UNIQUE (Email));
CREATE TABLE Student_Parent_Link (LinkID NUMBER GENERATED BY DEFAULT AS IDENTITY, StudentID VARCHAR2(255 CHAR), ParentID NUMBER, CONSTRAINT Student_Parent_Link_PK PRIMARY KEY (LinkID));
EXIT;